head.script:
scwin.screenId = "jldfil70805";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '4'); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='4'); } }, { id: "btn_EtnSub", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='5' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "btn_Register_4", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='4'); } }, { id: "btn_EtnSub_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='5' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "btn_Register_3", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '4'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_359", entity: "dlt_readDataLpVO", countIds: [], cells: [{ childId: "한글회사명_2", fn: function (v, i) { return String(v("lpMbrNm")); } }, { childId: "영문회사명_2", fn: function (v, i) { return String(v("lpMbrEngNm")); } }, { childId: "본점소재지_2", fn: function (v, i) { return String(v("lpMbrAddr")); } }, { childId: "담당자_2", fn: function (v, i) { return String(v("lpChrgNm")); } }, { childId: "연락처_2", fn: function (v, i) { return String(v("lpChrgTelNo")); } }, { childId: "기준년월_8", fn: function (v, i) { return String(v("lpAcntclsYymm1")); } }, { childId: "기준년월_9", fn: function (v, i) { return String(v("lpAcntclsYymm2")); } }, { childId: "기준년월_10", fn: function (v, i) { return String(v("lpAcntclsYymm3")); } }, { childId: "영업용순자본", fn: function (v, i) { return String(v("lpFbzNetcap1")); } }, { childId: "영업용순자본_2", fn: function (v, i) { return String(v("lpFbzNetcap2")); } }, { childId: "영업용순자본_3", fn: function (v, i) { return String(v("lpFbzNetcap3")); } }, { childId: "총위험액", fn: function (v, i) { return String(v("lpTotRiskAmt1")); } }, { childId: "총위험액_2", fn: function (v, i) { return String(v("lpTotRiskAmt2")); } }, { childId: "총위험액_3", fn: function (v, i) { return String(v("lpTotRiskAmt3")); } }, { childId: "필요유지 자기자본", fn: function (v, i) { return String(v("lpReqPersisPrincCapVal1")); } }, { childId: "필요유지 자기자본_2", fn: function (v, i) { return String(v("lpReqPersisPrincCapVal2")); } }, { childId: "필요유지 자기자본_3", fn: function (v, i) { return String(v("lpReqPersisPrincCapVal3")); } }, { childId: "(영업용)순자본비율", fn: function (v, i) { return String(v("lpNcr1")); } }, { childId: "(영업용)순자본비율_2", fn: function (v, i) { return String(v("lpNcr2")); } }, { childId: "(영업용)순자본비율_3", fn: function (v, i) { return String(v("lpNcr3")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.calIsuLimit();
        scwin.calRto($c.util.fieldEl('ipt_etnSrtyPrincCapRto1', 'etnSrtyPrincCapRto1'));
        scwin.calRto($c.util.fieldEl('ipt_etnSrtyPrincCapRto2', 'etnSrtyPrincCapRto2'));
        scwin.calRto($c.util.fieldEl('ipt_etnSrtyPrincCapRto3', 'etnSrtyPrincCapRto3'));
        scwin.insertComma(4);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70805.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70805.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

