                elem[i].name.indexOf('valuPrc1HistVoltPd') >= 0 ||
                elem[i].name.indexOf('valuPrc2HistVoltPd') >= 0 
            ) fn_ObjValueResetRmComma2(elem[i]);			
        }
    } else if(tab == 3) {
        for(var i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 || 
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
